from pathlib import Path
import sys,json
root=Path(__file__).resolve().parents[2];sys.path.insert(0,str(root/'_tools/pylibs312'))
import numpy as np,pandas as pd
p=Path(__file__).resolve().parents[1];o=p/'outputs';f=pd.read_csv(o/'screening_metrics.csv');s=pd.read_csv(o/'screening_summary.csv');a=pd.read_csv(o/'pool_audit.csv')
assert len(f)==480 and len(a)==12
for name in ['nbo','pcu']:
 candidate=pd.read_csv(o/f'candidates_{name}.csv');members=pd.read_csv(o/'training_membership.csv.gz');m=members[members.target==name]
 assert candidate.raw_row_id.is_unique
 for dose in [0,1]:assert m[m.support==dose].raw_row_id.is_unique and not set(candidate.raw_row_id)&set(m[m.support==dose].raw_row_id)
for path in o.glob('scores_*.npz'):
 z=np.load(path);parts=path.stem.split('_');target,dose,rep,model,seed=parts[1:];g=f[(f.target==target)&(f.support==int(dose))&(f.representation==rep)&(f.model==model)&(f.seed==int(seed))]
 for _,r in g.iterrows():
  k=int(r.k);pick=np.lexsort((z['raw_row_id'],-z['prediction']))[:k];best=np.lexsort((z['raw_row_id'],-z['y_true']))[:k]
  assert np.isclose(len(set(pick)&set(best))/k,r.recovery)
  assert np.isclose(z['y_true'][best].mean()-z['y_true'][pick].mean(),r.regret)
  assert np.isclose(z['y_true'][pick].mean()/z['y_true'].mean(),r.lift)
lines=['# Manuscript-ready text: fixed candidate-pool screening','','## Methods','We conducted a retrospective deployment simulation using two fixed, unseen-topology candidate pools (7,663 nbo and 31,682 pcu structures). The corresponding training sets comprised 4,991 and 4,719 structures, respectively, and contained no candidate-topology structures. Within each direction, training size, background rows and partner-topology proportion were fixed; geometrically matched partner subsets with 0% or 100% shared coarse compositions were substituted. These percentages describe the partner subset, not overall training coverage. Matching was approximate and residual chemical distribution differences remained.','', 'Three prespecified representations were compared: eight structural numerical descriptors (G); G plus categorical metal and functional-group identities (B); and B plus both linker identities (I). Categories were one-hot encoded using training-only vocabularies, with unknown categories encoded as all-zero blocks. Original linker slots were retained. Topology was excluded from model inputs. No validated linker-to-structure mapping was available, so transferable molecular descriptors were not evaluated. Random forest and ExtraTrees regressors each used 120 trees and five fixed random seeds without candidate-label-based tuning or calibration. Each model independently ranked the same candidate pool; predictions from different folds or models were not pooled.','', 'At budgets of 1%, 5%, 10% and 20% (rounded upward), we report top-k recovery, the true mean uptake of selected structures, regret relative to the oracle top-k mean, and lift over the expected mean of uniformly random selection. Ties were resolved by original row index. Standard deviations across seeds quantify model-randomness sensitivity conditional on the fixed data, rather than population uncertainty.','','## Results (illustrative prespecified 5% budget; all budgets in supplementary data)']
for target in ['nbo','pcu']:
 for rep in ['G','B','I']:
  g=s[(s.target==target)&(s.model=='RF')&(s.representation==rep)&(s.budget_fraction==.05)].sort_values('support');lo=g.iloc[0];hi=g.iloc[1]
  lines.append(f'For {target} with representation {rep}, replacing the nonshared partner subset by the shared subset changed recovery from {lo.recovery_mean:.3f} to {hi.recovery_mean:.3f}, selected mean uptake from {lo.selected_mean_mean:.3f} to {hi.selected_mean_mean:.3f} mmol/g, and regret from {lo.regret_mean:.3f} to {hi.regret_mean:.3f} mmol/g. The corresponding random-selection lifts were {lo.lift_mean:.2f} and {hi.lift_mean:.2f}.')
lines += ['', '## Limitations','The candidate pools had previously been evaluated in the replacement experiment; this analysis is retrospective, not an untouched confirmatory test. All predefined arms are reported, and the candidate labels were not used to select a deployment winner. The two directions concern one hMOF topology pair and provide neither independent experimental-database prediction validation nor a universal relationship between chemical support and screening utility. Transferable chemical representations remain an unresolved requirement. Any direction of benefit must be described by topology, representation, model and budget rather than assumed from coverage alone.','', 'Figure caption: Fixed-pool screening with random forests. Solid and dashed lines indicate shared and nonshared partner subsets, respectively; colors identify G, B and I representations. Error bars show standard deviations across five model seeds on fixed candidate and training sets. The dotted recovery line is the uniform-random expectation; it is not a fitted baseline.']
(p/'论文替换片段_固定候选池筛选.md').write_text('\n\n'.join(lines),encoding='utf-8')
(o/'verification.json').write_text(json.dumps(dict(status='passed',fits=120,metric_rows=480,candidate_hash_consistent=True,no_train_candidate_overlap=True,independently_recomputed=['recovery','regret','lift'],uncertainty_scope='model randomness conditional on fixed pools'),indent=2),encoding='utf-8')
print(s[(s.model=='RF')&(s.budget_fraction==.05)].to_string(index=False));print('VERIFIED')
